cat vitest.config.mts | grep -n "include\|setup\|environment"; mkdir -p src/components/settings/utils/__tests__ && cat > src/components/settings/utils/__tests__/tmpSearchCheck.test.ts <<'EOF'
import { describe, expect, it, vi } from "vitest";

vi.mock("~/utils/getDiscourseNodes", () => ({
  default: () => [
    { type: "uid-evd", text: "Evidence" },
    { type: "uid-iss", text: "Issue" },
  ],
  excludeDefaultNodes: () => true,
}));
vi.mock("~/components/settings/utils/accessors", () => ({ isSyncEnabled: () => true }));

const { buildSettingsCatalog } = await import("~/components/settings/utils/settingsCatalog");
const { rankSettings } = await import("~/components/settings/utils/settingsSearch");

const top = (query: string) =>
  rankSettings({ entries: buildSettingsCatalog(), query }).map(
    (e) => `${e.kind}:${e.label} [${e.breadcrumb}]`,
  );

describe("search feedback", () => {
  it.each(["Nodes", "Grammar", "Evidence", "Index", "Color", "canvas shortcut", "export", "issue index"])(
    "%s",
    (q) => {
      console.log(q, "=>\n  " + top(q).join("\n  "));
      expect(true).toBe(true);
    },
  );
  it("ids unique", () => {
    const ids = buildSettingsCatalog().map((e) => e.id);
    expect(new Set(ids).size).toBe(ids.length);
  });
});
EOF
