import path from "node:path";

const results = (page) =>
  page.evaluate(() =>
    [...document.querySelectorAll(".bp3-popover .bp3-menu .bp3-menu-item")].map(
      (el) => el.innerText.replace(/\n+/g, " | "),
    ),
  );

const surface = (page) =>
  page.evaluate(() => {
    const menu = document.querySelector(".bp3-popover .bp3-menu");
    const content = document.querySelector(".bp3-popover .bp3-popover-content");
    return {
      menuBg: menu && getComputedStyle(menu).backgroundColor,
      menuWidth: menu && menu.getBoundingClientRect().width,
      contentBg: content && getComputedStyle(content).backgroundColor,
      popoverShadow: content && getComputedStyle(content.closest(".bp3-popover")).boxShadow,
    };
  });

export default {
  readySelector: "input[placeholder='Search settings']",
  async run({ page, outDir }) {
    const input = page.locator("input[placeholder='Search settings']");
    const proof = {};
    const search = async (q, shot) => {
      await input.click();
      await input.fill(q);
      await page.waitForTimeout(300);
      proof[q] = await results(page);
      if (shot) await page.screenshot({ path: path.join(outDir, shot) });
    };
    await search("Grammar", "search-grammar.png");
    await search("Nodes", "search-nodes.png");
    proof.surface = await surface(page);
    await search("zzzz-no-match", "search-empty.png");
    proof.emptySurface = await surface(page);
    await search("Color", "search-color.png");
    const nodeType = (proof.Color[0] || "").split(" › ")[0];
    await search(nodeType, "search-node-type.png");
    await search("Color");
    await input.press("Enter");
    await page.waitForTimeout(250);
    proof.flash = await page.evaluate(() => {
